test("shard index is always within range", () => {
  // Fixed keys, so a key that hashes negative is exercised on every run and not by chance.
  let negativeHashes = 0;
  for (let i = 0; i < 200; i++) {
    const key = `req:${i}`;
    if (hashKey(key) < 0) negativeHashes++;
    const s = shardFor(key, 16);
    assert.ok(s >= 0 && s < 16, `${key} -> ${s}`);
  }
  assert.ok(negativeHashes > 0, "sample should cover negative hashes");
});

